'use strict';

/**
 * csrf.test.js
 *
 * Unit tests for the CSRF double-submit cookie middleware.
 * Tests that:
 *   - GET requests set a CSRF cookie and pass through
 *   - POST requests with valid X-CSRF-Token header matching the cookie pass through
 *   - POST requests with missing X-CSRF-Token header are blocked (403)
 *   - POST requests with mismatched X-CSRF-Token header are blocked (403)
 *   - POST requests with no CSRF cookie generate one and pass through (fresh session)
 *   - Webhook/callback endpoints are exempt from CSRF validation
 *   - OPTIONS requests are exempt from CSRF validation
 *   - The CSRF cookie has correct attributes (httpOnly=false, sameSite=strict)
 *
 * Run: NODE_ENV=test node --test src/middleware/csrf.test.js
 */

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const express = require('express');
const cookieParser = require('cookie-parser');
const crypto = require('crypto');
const supertest = require('supertest');

const { csrfProtection, CSRF_COOKIE_NAME, CSRF_HEADER_NAME } = require('./csrf');

// ---------------------------------------------------------------------------
// Helper: build a minimal Express app with CSRF protection
// ---------------------------------------------------------------------------
function buildApp() {
  const app = express();
  app.use(express.json());
  app.use(cookieParser());
  app.use(csrfProtection);

  // Safe routes (GET)
  app.get('/api/data', (_req, res) => res.json({ ok: true }));

  // State-changing routes (POST, PATCH, DELETE)
  app.post('/api/data', (_req, res) => res.json({ created: true }));
  app.patch('/api/data', (_req, res) => res.json({ updated: true }));
  app.delete('/api/data', (_req, res) => res.json({ deleted: true }));
  app.put('/api/data', (_req, res) => res.json({ replaced: true }));

  // Webhook endpoints (should be exempt from CSRF)
  app.post('/api/webhooks/kyc', (_req, res) => res.json({ webhook: true }));
  app.post('/api/webhooks/incoming/abc123', (_req, res) => res.json({ webhook: true }));
  app.post('/api/anchor/callbacks/sep24', (_req, res) => res.json({ webhook: true }));

  return app;
}

// ---------------------------------------------------------------------------
// Generate a valid CSRF token (simulates what the middleware sets as a cookie)
// ---------------------------------------------------------------------------
function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------
describe('CSRF middleware', () => {
  describe('GET requests', () => {
    it('sets a CSRF cookie on GET requests when none exists', async () => {
      const agent = supertest(buildApp());
      const res = await agent.get('/api/data');

      assert.equal(res.status, 200);
      const setCookie = res.headers['set-cookie'] || [];
      const csrfCookie = setCookie.find((c) => c.startsWith(`${CSRF_COOKIE_NAME}=`));
      assert.ok(csrfCookie, 'Expected CSRF cookie to be set');
      assert.ok(csrfCookie.includes('HttpOnly=false') || !csrfCookie.includes('HttpOnly=true'),
        'CSRF cookie should be readable by JavaScript (not httpOnly)');
      assert.ok(csrfCookie.includes('SameSite=Strict'), 'CSRF cookie should have SameSite=Strict');
    });

    it('passes through GET requests without validation', async () => {
      const agent = supertest(buildApp());
      const res = await agent.get('/api/data');

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { ok: true });
    });
  });

  describe('State-changing requests with valid CSRF token', () => {
    it('allows POST when X-CSRF-Token header matches the cookie', async () => {
      const agent = supertest(buildApp());
      const token = generateToken();

      const res = await agent
        .post('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${token}`)
        .set(CSRF_HEADER_NAME, token)
        .send({ name: 'test' });

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { created: true });
    });

    it('allows PATCH when X-CSRF-Token header matches the cookie', async () => {
      const agent = supertest(buildApp());
      const token = generateToken();

      const res = await agent
        .patch('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${token}`)
        .set(CSRF_HEADER_NAME, token)
        .send({ name: 'updated' });

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { updated: true });
    });

    it('allows DELETE when X-CSRF-Token header matches the cookie', async () => {
      const agent = supertest(buildApp());
      const token = generateToken();

      const res = await agent
        .delete('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${token}`)
        .set(CSRF_HEADER_NAME, token);

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { deleted: true });
    });

    it('allows PUT when X-CSRF-Token header matches the cookie', async () => {
      const agent = supertest(buildApp());
      const token = generateToken();

      const res = await agent
        .put('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${token}`)
        .set(CSRF_HEADER_NAME, token)
        .send({ name: 'replaced' });

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { replaced: true });
    });
  });

  describe('State-changing requests with invalid CSRF token', () => {
    it('blocks POST when X-CSRF-Token header is missing', async () => {
      const agent = supertest(buildApp());
      const token = generateToken();

      const res = await agent
        .post('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${token}`)
        .send({ name: 'test' });

      assert.equal(res.status, 403);
      assert.ok(res.body.error.includes('CSRF'));
    });

    it('blocks POST when X-CSRF-Token header does not match cookie', async () => {
      const agent = supertest(buildApp());
      const cookieToken = generateToken();
      const headerToken = generateToken();

      const res = await agent
        .post('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${cookieToken}`)
        .set(CSRF_HEADER_NAME, headerToken)
        .send({ name: 'test' });

      assert.equal(res.status, 403);
      assert.ok(res.body.error.includes('CSRF'));
    });

    it('blocks PATCH when X-CSRF-Token header is missing', async () => {
      const agent = supertest(buildApp());
      const token = generateToken();

      const res = await agent
        .patch('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${token}`)
        .send({ name: 'test' });

      assert.equal(res.status, 403);
    });

    it('blocks DELETE when X-CSRF-Token header is missing', async () => {
      const agent = supertest(buildApp());
      const token = generateToken();

      const res = await agent
        .delete('/api/data')
        .set('Cookie', `${CSRF_COOKIE_NAME}=${token}`);

      assert.equal(res.status, 403);
    });
  });

  describe('Fresh session (no CSRF cookie)', () => {
    it('generates a new CSRF cookie and allows POST when no cookie exists', async () => {
      const agent = supertest(buildApp());

      const res = await agent
        .post('/api/data')
        .send({ name: 'test' });

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { created: true });

      // Verify a new CSRF cookie was set
      const setCookie = res.headers['set-cookie'] || [];
      const csrfCookie = setCookie.find((c) => c.startsWith(`${CSRF_COOKIE_NAME}=`));
      assert.ok(csrfCookie, 'Expected CSRF cookie to be generated for fresh session');
    });
  });

  describe('Webhook/callback exemption', () => {
    it('allows POST to /api/webhooks/kyc without CSRF token', async () => {
      const agent = supertest(buildApp());

      const res = await agent
        .post('/api/webhooks/kyc')
        .send({ event: 'completed' });

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { webhook: true });
    });

    it('allows POST to /api/webhooks/incoming/:id without CSRF token', async () => {
      const agent = supertest(buildApp());

      const res = await agent
        .post('/api/webhooks/incoming/abc123')
        .send({ event: 'test' });

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { webhook: true });
    });

    it('allows POST to /api/anchor/callbacks/sep24 without CSRF token', async () => {
      const agent = supertest(buildApp());

      const res = await agent
        .post('/api/anchor/callbacks/sep24')
        .send({ event: 'test' });

      assert.equal(res.status, 200);
      assert.deepEqual(res.body, { webhook: true });
    });
  });

  describe('OPTIONS requests', () => {
    it('allows OPTIONS requests without CSRF validation (CORS preflight)', async () => {
      const agent = supertest(buildApp());

      const res = await agent
        .options('/api/data')
        .set('Access-Control-Request-Method', 'POST');

      assert.equal(res.status, 200);
    });
  });

  describe('Cookie attributes', () => {
    it('sets CSRF cookie with correct attributes', async () => {
      const agent = supertest(buildApp());
      const res = await agent.get('/api/data');

      const setCookie = res.headers['set-cookie'] || [];
      const csrfCookie = setCookie.find((c) => c.startsWith(`${CSRF_COOKIE_NAME}=`));
      assert.ok(csrfCookie, 'Expected CSRF cookie');

      // Cookie should be readable by JavaScript (not httpOnly)
      assert.ok(
        !csrfCookie.includes('HttpOnly') || csrfCookie.includes('HttpOnly=false'),
        'CSRF cookie should not be httpOnly'
      );

      // Should have SameSite=Strict
      assert.ok(csrfCookie.includes('SameSite=Strict'), 'Should have SameSite=Strict');

      // Should have path=/
      assert.ok(csrfCookie.includes('Path=/'), 'Should have Path=/');
    });
  });
});

'use strict';

// backend/src/middleware/embedAuth.js
//
// Validates the `embedToken` query param used by the public embeddable widgets,
// including the discovery widget (GET /api/embed/discover) and the campaign
// milestone progress bar (GET /api/embed/milestones/:campaignId).
// Attaches req.embedToken on success and ensures the token belongs to the
// requested campaign when a campaignId is present.
// Mirrors the style of middleware/auth.js's requireAuth.

const { validateEmbedToken } = require('../services/embedTokenService');
const asyncHandler = require('../utils/asyncHandler');

const requireEmbedToken = asyncHandler(async (req, res, next) => {
  const rawToken = req.query.embedToken;
  if (!rawToken) {
    return res.status(401).json({ error: 'embedToken is required' });
  }

  const tokenRow = await validateEmbedToken rawToken);
  if (!tokenRow) {
    return res.status(401).json({ error: 'Invalid or revoked embed token' });
  }

  const campaignId = req.params.campaignId || req.query.campaignId;
  if (campaignId && String(tokenRow.campaignId) !== String(campaignId)) {
    return res.status(403).json({ error: 'Embed token does not match campaign' });
  }

  req.embedToken = tokenRow;
  next();
});

module.exports = { requireEmbedToken };

const logger = require('../config/logger');

function normalizeErrorResponse(req, res, next) {
  const originalJson = res.json.bind(res);

  res.json = function json(body) {
    if (res.statusCode >= 400) {
      if (body && typeof body.error === 'string') {
        body = { error: { code: 'ERROR', message: body.error, fields: undefined } };
      } else if (body && body.error && typeof body.error === 'object' && !body.error.code) {
        body = {
          ...body,
          error: {
            code: 'ERROR',
            message: body.error.message || JSON.stringify(body.error),
            fields: body.error.fields,
          },
        };
      }
    }
    return originalJson(body);
  };

  next();
}

function errorHandler(err, req, res, next) {
  const status = err.statusCode || err.status || 500;
  const isServerError = status >= 500;
  const message = isServerError && process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message || 'Unexpected error';
  const payload = {
    code: err.code || (status === 422 ? 'VALIDATION_ERROR' : 'INTERNAL_ERROR'),
    message,
  };

  if (err.fields) {
    payload.fields = err.fields;
  }

  logger.error('Unhandled request error', {
    error: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
    status,
  });

  res.status(status).json({ error: payload });
}

module.exports = { normalizeErrorResponse, errorHandler };

const { body, param, query, validationResult } = require('express-validator');
const { Keypair } = require('@stellar/stellar-sdk');
const { getSupportedAssetCodes } = require('../services/stellarService');
const { stripHtml, sanitizeRichText } = require('../lib/sanitize');

const SUPPORTED_ASSETS = getSupportedAssetCodes();
const VALID_CAMPAIGN_STATUSES = ['active', 'funded', 'closed', 'failed'];
const VALID_ORDER_BY = ['newest', 'ending_soon', 'most_funded', 'most_backed', 'closest_to_goal', 'trending', 'relevance'];
const VALID_CATEGORIES = [
  'technology', 'community', 'arts', 'education',
  'environment', 'health', 'business', 'open_source', 'other',
];
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function isUuid(value) {
  return typeof value === 'string' && UUID_PATTERN.test(value);
}

function blankToNull(value) {
  return typeof value === 'string' && value.trim() === '' ? null : value;
}

const passwordValidation = [
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters long')
    .matches(/[a-z]/)
    .withMessage('Password must include a lowercase letter')
    .matches(/[A-Z]/)
    .withMessage('Password must include an uppercase letter')
    .matches(/[0-9]/)
    .withMessage('Password must include a number'),
];

const registerValidation = [
  body('email')
    .trim()
    .toLowerCase()
    .isEmail()
    .withMessage('Invalid email format'),
  ...passwordValidation,
  body('name')
    .customSanitizer(stripHtml)
    .notEmpty()
    .withMessage('Name is required'),
  body('wallet_type')
    .optional()
    .isIn(['custodial', 'freighter'])
    .withMessage('wallet_type must be custodial or freighter'),
  body('wallet_public_key')
    .optional()
    .custom((value, { req }) => {
      if (req.body.wallet_type === 'freighter') {
        try {
          Keypair.fromPublicKey(value);
          return true;
        } catch (_err) {
          throw new Error('wallet_public_key must be a valid Stellar public key');
        }
      }
      return true;
    }),
  body('role')
    .optional()
    .isIn(['contributor', 'creator'])
    .withMessage('Role must be contributor or creator'),
];

const loginValidation = [
  body('email')
    .trim()
    .toLowerCase()
    .isEmail()
    .withMessage('Invalid email format'),
  body('password').notEmpty().withMessage('Password is required'),
];

const forgotPasswordValidation = [
  body('email')
    .trim()
    .toLowerCase()
    .isEmail()
    .withMessage('Invalid email format'),
];

const resetPasswordValidation = [
  body('token').notEmpty().withMessage('Reset token is required'),
  ...passwordValidation,
];

const validateDeadline = (value) => {
  if (!value) return true;
  const deadline = new Date(value);
  const now = new Date();
  const minFutureTime = now.getTime() + 24 * 60 * 60 * 1000;
  if (isNaN(deadline.getTime()) || deadline.getTime() < minFutureTime) {
    throw new Error('Deadline must be at least 24 hours in the future');
  }
  return true;
};

const createCampaignValidation = [
  body('title')
    .customSanitizer(stripHtml)
    .notEmpty()
    .withMessage('Title is required')
    .isLength({ max: 100 })
    .withMessage('Title must be at most 100 characters'),
  body('category')
    .optional({ nullable: true })
    .customSanitizer(stripHtml)
    .isLength({ max: 50 })
    .withMessage('Category must be at most 50 characters'),
  body('description')
    .optional({ nullable: true })
    .customSanitizer(sanitizeRichText)
    .isLength({ max: 1000 })
    .withMessage('Description must be at most 1000 characters'),
  body('target_amount')
    .exists()
    .withMessage('Target amount is required')
    .isFloat({ gt: 0 })
    .withMessage('Target amount must be greater than zero'),
  body('asset_type')
    .notEmpty()
    .withMessage('Asset type is required')
    .isIn(SUPPORTED_ASSETS)
    .withMessage(`Asset type must be one of: ${SUPPORTED_ASSETS.join(', ')}`),
  body('template_id')
    .optional({ nullable: true, checkFalsy: true })
    .custom(isUuid)
    .withMessage('template_id must be a valid UUID'),
  body('deadline')
    .optional({ nullable: true, checkFalsy: true })
    .isISO8601()
    .withMessage('Deadline must be a valid ISO 8601 date (preferably with Z suffix for UTC)')
    .custom(validateDeadline),
  body('min_contribution')
    .optional({ nullable: true, checkFalsy: true })
    .isFloat({ gt: 0 })
    .withMessage('Minimum contribution must be greater than zero'),
];

const updateCampaignValidation = [
  body('deadline')
    .optional({ nullable: true, checkFalsy: true })
    .isISO8601()
    .withMessage('Deadline must be a valid ISO 8601 date')
    .custom(validateDeadline),
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: errors.array()[0].msg, errors: errors.array() });
  }
  next();
};

module.exports = {
  registerValidation,
  loginValidation,
  forgotPasswordValidation,
  resetPasswordValidation,
  createCampaignValidation,
  updateCampaignValidation,
  handleValidationErrors,
  isUuid,
  blankToNull,
  CAMPAIGN_UPDATE_BODY_MAX_LENGTH: 5000,
};

const router = require('express').Router();
const db = require('../config/database');
const { requireAuth } = require('../middleware/auth');
const { requireAdmin } = require('../middleware/authScopes');
const asyncHandler = require('../utils/asyncHandler');
const { getFraudDashboard, resolveFlaggedContribution, retrainModel } = require('../services/fraudService');

router.use(requireAuth, requireAdmin);

/**
 * @openapi
 * /api/admin/fraud/dashboard:
 *   get:
 *     summary: Get fraud dashboard data
 */
router.get('/fraud/dashboard', asyncHandler(async (req, res) => {
  const status = req.query.status;
  const limit = parseInt(req.query.limit || '50', 10);
  const offset = parseInt(req.query.offset || '0', 10);

  const items = await getFraudDashboard({ status, limit, offset });
  res.json({ items });
}));

/**
 * @openapi
 * /api/admin/fraud/contributions/{id}/resolve:
 *   post:
 *     summary: Approve or reject flagged contribution
 */
router.post('/fraud/contributions/:id/resolve', asyncHandler(async (req, res) => {
  const { id } = req.params;
  const { resolution } = req.body;
  const adminUserId = req.user.userId;

  const updated = await resolveFlaggedContribution({
    contributionId: id,
    resolution,
    adminUserId,
  });

  res.json({ success: true, contribution: updated });
}));

/**
 * @openapi
 * /api/admin/fraud/retrain:
 *   post:
 *     summary: Retrain fraud scoring model
 */
router.post('/fraud/retrain', asyncHandler(async (req, res) => {
  const result = await retrainModel();
  res.json(result);
}));

module.exports = router;

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const express = require('express');
const request = require('supertest');
const proxyquire = require('proxyquire').noCallThru();

function buildApp({ queryImpl, authUser, revokeAndCloseImpl } = {}) {
  const dbStub = { query: queryImpl };

  const authMiddleware = {
    requireAuth: (req, res, next) => {
      if (!authUser) return res.status(401).json({ error: 'Unauthorized' });
      req.user = authUser;
      next();
    },
    requireAdmin: (req, res, next) => {
      if (!req.user?.is_admin) return res.status(403).json({ error: 'Forbidden' });
      next();
    },
    IMPERSONATION_TOKEN_COOKIE_NAME: 'impersonation_token',
  };

  const adminRouter = proxyquire('./admin', {
    '../config/database': dbStub,
    '../middleware/auth': authMiddleware,
    '../services/reconciliation': {
      reconcileSingleCampaign: async () => ({ message: 'ok' }),
      getRecentReconciliationRuns: () => [],
    },
    '../config/stellar': {
      server: {
        ledgers: () => ({ order: () => ({ limit: () => ({ call: async () => ({ records: [{ sequence: 123 }] }) }) }) }),
        feeStats: async () => ({ last_ledger_base_fee: 100 }),
      },
    },
    '../services/sorobanService': {
      deployCampaignContracts: async () => ({}),
    },
    '../services/webhookDispatcher': {
      processDelivery: async () => {},
      processCampaignWebhookDelivery: async () => {},
    },
    '../utils/cache': {
      invalidate: () => {},
      invalidatePrefix: () => {},
    },
    '../utils/pagination': {
      parsePagination: (query, defaults) => ({
        limit: parseInt(query.limit) || defaults.limit || 50,
        offset: parseInt(query.offset) || 0,
      }),
    },
    '../services/stellarService': {
