/**
 * Contributor Identity routes — issue #689
 *
 * POST   /api/contributor/identity/register           authenticated; idempotent
 * GET    /api/contributor/identity/:publicKey          public
 * GET    /api/contributor/identity/:publicKey/verify   public; ?attestation=kyc_standard
 */

const router = require('express').Router();
const { param, query, validationResult } = require('express-validator');
const { requireAuth, optionalAuth } = require('../middleware/auth');
const asyncHandler = require('../utils/asyncHandler');
const logger = require('../config/logger');
const db = require('../config/database');
const {
  registerIdentity,
  getContributorProfile,
  verifyAttestation,
} = require('../services/contributorIdentityService');

const VALID_ATTESTATION_TYPES = ['kyc_basic', 'kyc_standard', 'kyc_enhanced'];

function validateRequest(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(422).json({
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Invalid request parameters',
        fields: Object.fromEntries(errors.array().map((e) => [e.path, e.msg])),
      },
    });
  }
  next();
}

/**
 * POST /api/contributor/identity/register
 *
 * Register the authenticated user's Stellar public key on the identity
 * contract and in the contributor_identities table.  Idempotent.
 */
router.post(
  '/register',
  requireAuth,
  asyncHandler(async (req, res) => {
    const { userId } = req.user;

    // Fetch the user's wallet public key
    const { rows } = await db.query(
      'SELECT wallet_public_key FROM users WHERE id = $1',
      [userId]
    );
    if (!rows.length) {
      return res.status(404).json({ error: 'User not found' });
    }

    const publicKey = rows[0].wallet_public_key;
    if (!publicKey) {
      return res.status(400).json({ error: 'User does not have a Stellar wallet linked' });
    }

    const identity = await registerIdentity(publicKey, userId);

    res.status(200).json({
      did: identity.did,
      public_key: identity.public_key,
      contract_registered_at: identity.contract_registered_at,
      created_at: identity.created_at,
    });
  })
);

/**
 * GET /api/contributor/identity/:publicKey
 *
 * Public endpoint.  Returns DID, reputation score, attestation types (no PII),
 * and aggregated contribution stats.
 */
router.get(
  '/:publicKey',
  [
    param('publicKey')
      .isString()
      .trim()
      .matches(/^G[A-Z2-7]{55}$/)
      .withMessage('publicKey must be a valid Stellar public key'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { publicKey } = req.params;
    const profile = await getContributorProfile(publicKey);
    res.json(profile);
  })
);

/**
 * GET /api/contributor/identity/:publicKey/verify?attestation=kyc_standard
 *
 * Used by campaign creators to gate contributions based on KYC level without
 * accessing personal data.  Returns { verified, expiresAt }.
 */
router.get(
  '/:publicKey/verify',
  [
    param('publicKey')
      .isString()
      .trim()
      .matches(/^G[A-Z2-7]{55}$/)
      .withMessage('publicKey must be a valid Stellar public key'),
    query('attestation')
      .isIn(VALID_ATTESTATION_TYPES)
      .withMessage(`attestation must be one of: ${VALID_ATTESTATION_TYPES.join(', ')}`),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { publicKey } = req.params;
    const attestationType = req.query.attestation;
    const result = await verifyAttestation(publicKey, attestationType);
    res.json(result);
  })
);

module.exports = router;

const express = require('express');
const router = express.Router();
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const db = require('../config/database');
const asyncHandler = require('../utils/asyncHandler');
const { embedStatsLimiter } = require('../middleware/rateLimiter');
const { requireAuth } = require('../middleware/auth');
const { requireEmbedToken } = require('../middleware/embedAuth');
const { getTrendingCampaigns } = require('../services/trendingService');
const {
  signEmbedToken,
  verifyEmbedToken,
  validateOrigin,
} = require('../services/embedTokenJwtService');
const { evaluateCampaign } = require('../services/fraudService');
const { createNotification } = require('../services/notifications');

const DESCRIPTION_TRUNCATE_LENGTH = 140;

/**
 * Build the Content-Security-Policy for the embed widget from environment
 * variables so dev/staging/self-hosted deployments work without hardcoding
 * api.crowdpay.com. The WebSocket protocol is derived from the backend URL
 * and localhost origins are only permitted in non-production environments.
 */
function buildEmbedCsp() {
  const backendUrl = new URL(process.env.BACKEND_URL || 'http://localhost:3001');
  const wsProtocol = backendUrl.protocol === 'https:' ? 'wss:' : 'ws:';

  const connectSrc = [backendUrl.host, `${wsProtocol}//${backendUrl.host}`];

  if (process.env.NODE_ENV !== 'production') {
    connectSrc.push('http://localhost:3001', 'ws://localhost:3001');
  }

  return (
    `frame-ancestors *; ` +
    `default-src 'self'; ` +
    `connect-src ${connectSrc.join(' ')}; ` +
    `script-src 'self'; ` +
    `style-src 'self'`
  );
}

function truncateDescription(description) {
  if (!description) return '';
  return description.length > DESCRIPTION_TRUNCATE_LENGTH
    ? `${description.slice(0, DESCRIPTION_TRUNCATE_LENGTH).trim()}...`
    : description;
}

function extractEmbedToken(req) {
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    return authHeader.substring(7).trim();
  }
  if (req.query && req.query.token) {
    return String(req.query.token).trim();
  }
  return null;
}

/**
 * Middleware for validating embed token & origin.
 */
async function authenticateEmbedToken(req, res, next) {
  const token = extractEmbedToken(req);
  if (!token) {
    return res.status(401).json({ error: 'Embed token required in Authorization header' });
  }

  const payload = verifyEmbedToken(token);
  if (!payload || !payload.sub) {
    return res.status(401).json({ error: 'Invalid or expired embed token' });
  }

  if (req.params.campaignId && payload.sub !== req.params.campaignId) {
    return res.status(401).json({ error: 'Embed token does not match campaign ID' });
  }

  const originHeader = req.headers.origin || req.get('origin');
  if (originHeader && !validateOrigin(originHeader, payload.origins)) {
    return res.status(403).json({ error: 'Origin not allowed for this embed token' });
  }

  const { rows } = await db.query(
    `SELECT * FROM embed_tokens WHERE campaign_id = $1 AND (expires_at IS NULL OR expires_at > NOW()) ORDER BY created_at DESC LIMIT 1`,
    [payload.sub]
  );

  if (rows.length === 0) {
    return res.status(401).json({ error: 'Embed token expired or revoked' });
  }

  const activeToken = rows[0];
  db.query(`UPDATE embed_tokens SET last_used_at = NOW(), use_count = use_count + 1 WHERE id = $1`, [activeToken.id]).catch(() => {});

  req.embedPayload = payload;
  req.embedTokenRow = activeToken;
  next();
}

