      .withMessage('Title must be at most 255 characters'),
    body('content')
      .trim()
      .notEmpty()
      .withMessage('Content is required'),
    body('summary')
      .optional()
      .trim()
      .isLength({ max: 500 })
      .withMessage('Summary must be at most 500 characters'),
    body('images')
      .optional()
      .isArray()
      .withMessage('Images must be an array'),
