test('POST /api/milestones/:id/approve prevents concurrent approval via atomic claim', async () => {
  let claimCount = 0;
  const calls = [];
  const { app, cleanup } = buildApp({
    userId: 'platform-1',
    role: 'admin',
    platformApproverUserId: 'platform-1',
    queryImpl: async (text, params) => {
      calls.push(text);
