                  backer_count: '2',
                  deadline: '2026-06-01',
                },
              ],
            };
          }
          return { rows: [] };
        },
        release: () => {},
      }),
    },
    '../config/logger': {
      info: (message, meta) => {
        if (message === 'Campaign status transition') loggedTransitions.push(meta);
      },
      error: () => {},
