  createProposal,
  voteOnProposal,
  executeProposal,
  syncProposalData,
  setVoteDelegation,
  revokeVoteDelegation,
  getDelegateForWallet,
  getEffectiveVoteWeight,
  getAllTransitiveDelegatorWallets,
};

