        forAccount: () => ({
          cursor: () => ({
            order: () => ({
              limit: () => ({
                call: async () => ({ records: [] }),
              }),
            }),
            stream: (callbacks) => {
              return () => {};
            },
          }),
        }),
      }),
    },
  };

  const mockLogger = {
    info: () => {},
    warn: () => {},
    error: () => {},
  };

  const { HorizonIngestionWorker, defaultIngestionWorker } = proxyquire(
    "./horizonIngestionWorker",
    {
      "../config/database": mockDb,
      "../config/stellar": mockStellar,
