'use strict';

const db = require('../config/database');
const { TtlCache } = require('../utils/TtlCache');
const { evaluateBadges } = require('./badgeService');

// Cache per-user dashboard data for 60 seconds.
// Key scheme: "campaigns:<userId>" and "contributions:<userId>"
const dashboardCache = new TtlCache(60_000);

async function listCreatorCampaignsCached(userId) {
  const key = `campaigns:${userId}`;
  return dashboardCache.wrap(key, async () => {
    const { rows } = await db.query(
      `SELECT c.id, c.title, c.status, c.asset_type, c.target_amount, c.raised_amount,
              c.deadline, c.created_at,
              COALESCE(stats.contributor_count, 0) AS contributor_count,
              EXISTS (
                SELECT 1 FROM milestones m WHERE m.campaign_id = c.id LIMIT 1
              ) AS has_milestones
       FROM campaigns c
       LEFT JOIN LATERAL (
         SELECT COUNT(DISTINCT sender_public_key)::int AS contributor_count
         FROM contributions ctr
         WHERE ctr.campaign_id = c.id
       ) stats ON TRUE
       WHERE c.creator_id = $1
       ORDER BY c.created_at DESC`,
      [userId]
    );
    return rows;
  });
}

// Whitelisted columns for ?fields= on GET /campaigns/mine.
// Keeps SQL injection-safe field selection for lightweight consumers
// (e.g. NotificationSettings only needs id/title/status/raised_amount).
const CREATOR_CAMPAIGN_FIELDS = {
  id: 'c.id',
  title: 'c.title',
  status: 'c.status',
  asset_type: 'c.asset_type',
  target_amount: 'c.target_amount',
  raised_amount: 'c.raised_amount',
  deadline: 'c.deadline',
  created_at: 'c.created_at',
  is_hidden: 'c.is_hidden',
  contributor_count:
    'COALESCE(stats.contributor_count, 0) AS contributor_count',
  has_milestones: `EXISTS (
              SELECT 1 FROM milestones m WHERE m.campaign_id = c.id LIMIT 1
            ) AS has_milestones`,
};

const DEFAULT_CREATOR_CAMPAIGN_FIELDS = [
  'id',
  'title',
  'status',
  'asset_type',
  'target_amount',
  'raised_amount',
  'deadline',
  'created_at',
  'is_hidden',
  'contributor_count',
  'has_milestones',
];

function parseCreatorCampaignFields(fieldsParam) {
  if (fieldsParam === undefined || fieldsParam === null || fieldsParam === '') {
    return DEFAULT_CREATOR_CAMPAIGN_FIELDS;
  }
  const requested = String(fieldsParam)
    .split(',')
    .map((f) => f.trim())
    .filter(Boolean);
  const selected = [];
  for (const name of requested) {
    if (CREATOR_CAMPAIGN_FIELDS[name] && !selected.includes(name)) {
      selected.push(name);
    }
  }
  if (!selected.length) return DEFAULT_CREATOR_CAMPAIGN_FIELDS;
  // Always include id so clients can key list items.
  if (!selected.includes('id')) selected.unshift('id');
  return selected;
}

async function listCreatorCampaigns(userId, options = {}) {
  const page = Math.max(1, parseInt(options.page, 10) || 1);
  const limit = Math.min(Math.max(1, parseInt(options.limit, 10) || 20), 100);
  const offset = (page - 1) * limit;
  const selectedFields = parseCreatorCampaignFields(options.fields);
  const needsContributorCount = selectedFields.includes('contributor_count');
  const selectSql = selectedFields.map((name) => CREATOR_CAMPAIGN_FIELDS[name]).join(',\n            ');
  const joinSql = needsContributorCount
    ? `LEFT JOIN LATERAL (
       SELECT COUNT(DISTINCT sender_public_key)::int AS contributor_count
       FROM contributions ctr
       WHERE ctr.campaign_id = c.id
     ) stats ON TRUE`
    : '';

  const countResult = await db.query(
    'SELECT COUNT(*)::int AS total FROM campaigns WHERE creator_id = $1',
    [userId]
  );
  const total = countResult.rows[0]?.total || 0;
  const totalPages = Math.ceil(total / limit);

  const { rows } = await db.query(
    `SELECT ${selectSql}
     FROM campaigns c
     ${joinSql}
     WHERE c.creator_id = $1
     ORDER BY c.created_at DESC
     LIMIT $2 OFFSET $3`,
    [userId, limit, offset]
  );

  return {
    data: rows,
    pagination: { page, limit, total, totalPages },
  };
}

async function listUserContributions(userId) {
  const key = `contributions:${userId}`;
  return dashboardCache.wrap(key, async () => {
    const { rows: userRows } = await db.query(
      'SELECT wallet_public_key FROM users WHERE id = $1',
      [userId]
    );
    if (!userRows.length) return null;

    const senderPublicKey = userRows[0].wallet_public_key;
    const { rows } = await db.query(
      `SELECT ctr.id, ctr.amount, ctr.asset, ctr.anchor_id, ctr.anchor_transaction_id,
              ctr.source_amount, ctr.source_asset, ctr.conversion_rate, ctr.payment_type,
              ctr.tx_hash, ctr.created_at,
              c.id AS campaign_id, c.title AS campaign_title, c.status AS campaign_status,
              c.target_amount, c.raised_amount
       FROM contributions ctr
       JOIN campaigns c ON c.id = ctr.campaign_id
       WHERE ctr.sender_public_key = $1
       ORDER BY ctr.created_at DESC`,
      [senderPublicKey]
    );
    return rows;
  });
}

/**
 * Invalidate all cached dashboard data for a given user.
 * Call this after a contribution is made or a campaign status changes.
 * @param {string} userId
 */
function invalidateUserDashboard(userId) {
  dashboardCache.invalidatePrefix(`campaigns:${userId}`);
  dashboardCache.invalidatePrefix(`contributions:${userId}`);
}

const ACTIVE_CAMPAIGN_STATUSES = new Set(['active', 'funded']);
const COMPLETED_CAMPAIGN_STATUSES = new Set(['completed', 'funded', 'withdrawn']);

async function getContributorDashboard(userId) {
  const { rows: userRows } = await db.query(
    'SELECT wallet_public_key FROM users WHERE id = $1',
    [userId]
  );
  if (!userRows.length) return null;

  const senderPublicKey = userRows[0].wallet_public_key;

  const { rows: contribs } = await db.query(
    `SELECT ctr.id, ctr.amount, ctr.asset, ctr.tx_hash, ctr.created_at,
            ctr.contract_refunded_at, ctr.contract_refund_tx_hash,
            c.id AS campaign_id, c.title AS campaign_title, c.status AS campaign_status,
            c.target_amount, c.raised_amount, c.asset_type, c.deadline, c.escrow_contract_id
     FROM contributions ctr
     JOIN campaigns c ON c.id = ctr.campaign_id
     WHERE ctr.sender_public_key = $1
     ORDER BY ctr.created_at DESC`,
    [senderPublicKey]
  );

  if (!contribs.length) {
    const emptyStats = {
      total_contributed: 0,
      active_campaigns_backed: 0,
      total_refunded: 0,
      campaigns_backed: 0,
      campaigns_completed: 0,
      avg_contribution: 0,
    };
    return {
      stats: { ...emptyStats, badges: await evaluateBadges(userId) },
      campaigns: [],
    };
  }

  const campaignIds = [...new Set(contribs.map((row) => row.campaign_id))];

  const { rows: milestones } = await db.query(
    `SELECT id, campaign_id, title, release_percentage, sort_order, status
     FROM milestones
     WHERE campaign_id = ANY($1::int[])
     ORDER BY campaign_id, sort_order ASC`,
    [campaignIds]
  );

  const milestonesByCampaign = {};
  for (const milestone of milestones) {
    if (!milestonesByCampaign[milestone.campaign_id]) {
      milestonesByCampaign[milestone.campaign_id] = [];
    }
    milestonesByCampaign[milestone.campaign_id].push({
      id: milestone.id,
      title: milestone.title,
      release_percentage: Number(milestone.release_percentage),
      status: milestone.status,
    });
  }

  const campaignsMap = new Map();
  let totalContributed = 0;
  let totalRefunded = 0;

  for (const row of contribs) {
    const amount = Number(row.amount);
    totalContributed += amount;
    if (row.contract_refunded_at) totalRefunded += amount;

    if (!campaignsMap.has(row.campaign_id)) {
      campaignsMap.set(row.campaign_id, {
        campaign_id: row.campaign_id,
        title: row.campaign_title,
        status: row.campaign_status,
        target_amount: Number(row.target_amount),
        raised_amount: Number(row.raised_amount),
        asset_type: row.asset_type,
        deadline: row.deadline,
        escrow_contract_id: row.escrow_contract_id,
        contributed_amount: 0,
        contributions: [],
        milestones: milestonesByCampaign[row.campaign_id] || [],
      });
    }

    const campaign = campaignsMap.get(row.campaign_id);
    campaign.contributed_amount += amount;
    campaign.contributions.push({
      id: row.id,
      amount,
      asset: row.asset,
      tx_hash: row.tx_hash,
      created_at: row.created_at,
      refund_status: row.contract_refunded_at
        ? 'processed'
        : row.campaign_status === 'failed'
          ? 'pending'
          : null,
      refund_tx_hash: row.contract_refund_tx_hash,
    });
  }

  const allCampaigns = [...campaignsMap.values()];
  const activeCampaignsBacked = allCampaigns.filter((campaign) =>
    ACTIVE_CAMPAIGN_STATUSES.has(campaign.status)
  ).length;
  const campaignsCompleted = allCampaigns.filter((campaign) =>
    COMPLETED_CAMPAIGN_STATUSES.has(campaign.status)
  ).length;

  const stats = {
    total_contributed: totalContributed,
    active_campaigns_backed: activeCampaignsBacked,
    total_refunded: totalRefunded,
    campaigns_backed: allCampaigns.length,
    campaigns_completed: campaignsCompleted,
    avg_contribution: contribs.length ? totalContributed / contribs.length : 0,
  };

  return {
    stats: { ...stats, badges: await evaluateBadges(userId) },
    campaigns: allCampaigns,
  };
}

function csvEscape(value) {
  const str = (value === null || value === undefined) ? '' : String(value);
  if (/[",\n]/.test(str)) {
    return `"${str.replace(/"/g, '""')}"`;
  }
  return str;
}

async function getContributorDashboardCsv(userId) {
  const dashboard = await getContributorDashboard(userId);
  if (!dashboard) return null;

  const header = ['date', 'campaign', 'amount', 'asset', 'tx_hash', 'refund_status'];
  const rows = [header.join(',')];

  for (const campaign of dashboard.campaigns) {
    for (const contribution of campaign.contributions) {
      rows.push(
        [
          new Date(contribution.created_at).toISOString(),
          campaign.title,
          contribution.amount,
          contribution.asset,
          contribution.tx_hash || '',
          contribution.refund_status || '',
        ]
          .map(csvEscape)
          .join(',')
      );
    }
  }

  return rows.join('\n');
}

module.exports = {
  listCreatorCampaigns,
  listUserContributions,
  invalidateUserDashboard,
  // Exported for testing
  _dashboardCache: dashboardCache,
  getContributorDashboard,
  getContributorDashboardCsv,
};

const db = require('../config/database');

async function getCampaignVelocity(campaignId) {
  const { rows: campaignRows } = await db.query(
    `SELECT c.id, c.category, c.target_amount, c.raised_amount, c.deadline,
            COALESCE(c.velocity_alert_threshold, 0) AS velocity_alert_threshold
     FROM campaigns c WHERE c.id = $1`,
    [campaignId]
  );
  if (!campaignRows.length) throw new Error('Campaign not found');
  const campaign = campaignRows[0];

  const targetAmount = Number(campaign.target_amount || 0);
  const raisedAmount = Number(campaign.raised_amount || 0);
  const remainingAmount = Math.max(0, targetAmount - raisedAmount);

  const { rows: txRows } = await db.query(
    `SELECT amount, created_at FROM contributions
     WHERE campaign_id = $1 AND status = 'confirmed'
     ORDER BY created_at ASC`,
    [campaignId]
  );

  const now = Date.now();
  const sumSince = (msAgo) => {
    const cutoff = new Date(now - msAgo);
    return txRows
      .filter(t => new Date(t.created_at) >= cutoff)
      .reduce((acc, t) => acc + Number(t.amount), 0);
  };

  const raised7d = sumSince(7 * 24 * 60 * 60 * 1000);
  const raised30d = sumSince(30 * 24 * 60 * 60 * 1000);

  const hourly = raised7d / (7 * 24);
  const daily = raised7d / 7;
  const weekly = raised7d;

  let projectedCompletionDate = null;
  if (hourly > 0 && remainingAmount > 0) {
    const hoursNeeded = remainingAmount / hourly;
    projectedCompletionDate = new Date(now + hoursNeeded * 3600 * 1000).toISOString();
  } else if (remainingAmount === 0) {
    projectedCompletionDate = new Date().toISOString();
  }

  const { rows: catRows } = await db.query(
    `SELECT AVG(cat_stats.weekly_raised) AS category_avg_weekly
     FROM (
       SELECT c.id, COALESCE(SUM(co.amount), 0) AS weekly_raised
       FROM campaigns c
       LEFT JOIN contributions co ON co.campaign_id = c.id AND co.status = 'confirmed' AND co.created_at >= NOW() - INTERVAL '7 days'
       WHERE c.category = $1 AND c.id != $2
       GROUP BY c.id
     ) cat_stats`,
    [campaign.category || 'other', campaignId]
  );
  const categoryAverageWeekly = Number(catRows[0]?.category_avg_weekly || 0);
  const categoryAverageHourly = categoryAverageWeekly / (7 * 24);

  const threshold = Number(campaign.velocity_alert_threshold || 0);
  const isBelowAlertThreshold = threshold > 0 && hourly < threshold;

  const trend7d = [];
  for (let i = 6; i >= 0; i--) {
    const dayStart = new Date(now - i * 24 * 3600 * 1000);
    dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(dayStart.getTime() + 24 * 3600 * 1000);
    const amt = txRows
      .filter(t => {
        const d = new Date(t.created_at);
        return d >= dayStart && d < dayEnd;
      })
      .reduce((sum, t) => sum + Number(t.amount), 0);
    trend7d.push({
      date: dayStart.toISOString().split('T')[0],
      amount: amt,
    });
  }

  const trend30d = [];
  for (let i = 29; i >= 0; i--) {
    const dayStart = new Date(now - i * 24 * 3600 * 1000);
    dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(dayStart.getTime() + 24 * 3600 * 1000);
    const amt = txRows
      .filter(t => {
        const d = new Date(t.created_at);
        return d >= dayStart && d < dayEnd;
      })
      .reduce((sum, t) => sum + Number(t.amount), 0);
    trend30d.push({
      date: dayStart.toISOString().split('T')[0],
      amount: amt,
    });
  }

  return {
    velocity: {
      amount_per_hour: Math.round(hourly * 100) / 100,
      amount_per_day: Math.round(daily * 100) / 100,
      amount_per_week: Math.round(weekly * 100) / 100,
    },
    projected_completion_date: projectedCompletionDate,
    category_comparison: {
      category: campaign.category || 'other',
      category_avg_weekly: Math.round(categoryAverageWeekly * 100) / 100,
      category_avg_hourly: Math.round(categoryAverageHourly * 100) / 100,
    },
    alerts: {
      threshold,
      is_below_threshold: isBelowAlertThreshold,
    },
    trends: {
      view_7d: trend7d,
      view_30d: trend30d,
    },
  };
}

async function updateCampaignVelocityAlertThreshold(campaignId, threshold) {
  await db.query(
    `UPDATE campaigns SET velocity_alert_threshold = $1 WHERE id = $2`,
    [threshold, campaignId]
  );
  return { success: true, threshold };
}

module.exports = {
  getCampaignVelocity,
  updateCampaignVelocityAlertThreshold,
};

const crypto = require('crypto');
const https = require('https');
const { Keypair } = require('@stellar/stellar-sdk');
const db = require('../config/database');

const ENVELOPE_PREFIX = 'cpws:v1:';
const LOCAL_PROVIDER = 'local';
const AWS_KMS_PROVIDER = 'aws-kms';

function isProduction() {
  return process.env.NODE_ENV === 'production';
}

function getConfiguredProvider() {
  if (process.env.WALLET_SECRET_PROVIDER) return process.env.WALLET_SECRET_PROVIDER;
  return isProduction() ? AWS_KMS_PROVIDER : LOCAL_PROVIDER;
}

function decodeKeyMaterial(value) {
  const input = String(value || '').trim();
  if (!input) {
    throw new Error('WALLET_SECRET_LOCAL_KEK must be set for local wallet-secret encryption');
  }

  if (/^[0-9a-fA-F]{64}$/.test(input)) {
    return Buffer.from(input, 'hex');
  }

  try {
    return Buffer.from(input, 'base64');
  } catch (_err) {
    throw new Error('WALLET_SECRET_LOCAL_KEK must be base64 or hex encoded');
  }
}

function getLocalKek() {
  const key = decodeKeyMaterial(process.env.WALLET_SECRET_LOCAL_KEK);
  if (key.length !== 32) {
    throw new Error('WALLET_SECRET_LOCAL_KEK must decode to exactly 32 bytes');
  }
  return key;
}

function buildEncryptionContext({ userId, walletPublicKey }) {
  const context = {
    app: 'crowdpay',
    entity: 'user-wallet-secret',
  };

  if (userId) context.user_id = String(userId);
  if (walletPublicKey) context.wallet_public_key = String(walletPublicKey);
  return context;
}

function bufferToB64(value) {
  return Buffer.from(value).toString('base64');
}

function b64ToBuffer(value) {
  return Buffer.from(String(value), 'base64');
}

function encodeEnvelope(payload) {
  return `${ENVELOPE_PREFIX}${Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url')}`;
}

function parseEnvelope(value) {
  if (typeof value !== 'string' || !value.startsWith(ENVELOPE_PREFIX)) return null;
  const encoded = value.slice(ENVELOPE_PREFIX.length);
  const decoded = Buffer.from(encoded, 'base64url').toString('utf8');
  const payload = JSON.parse(decoded);
  if (!payload || payload.kind !== 'wallet-secret-envelope' || payload.v !== 1) {
    throw new Error('Unsupported wallet secret envelope');
  }
  return payload;
}

function isEncryptedWalletSecret(value) {
  try {
    return Boolean(parseEnvelope(value));
  } catch (_err) {
    return false;
  }
}

function isLegacyPlaintextWalletSecret(value) {
  if (typeof value !== 'string' || !value || isEncryptedWalletSecret(value)) return false;
  try {
    Keypair.fromSecret(value);
    return true;
  } catch (_err) {
    return false;
  }
}

function createAesGcmCipher(key, iv, aad) {
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  if (aad) cipher.setAAD(aad);
  return cipher;
}

function createAesGcmDecipher(key, iv, aad, tag) {
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  if (aad) decipher.setAAD(aad);
  decipher.setAuthTag(tag);
  return decipher;
}

function encryptAesGcm({ plaintext, key, aad }) {
  const iv = crypto.randomBytes(12);
  const cipher = createAesGcmCipher(key, iv, aad);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return { iv, ciphertext, tag };
}

function decryptAesGcm({ ciphertext, key, iv, aad, tag }) {
  const decipher = createAesGcmDecipher(key, iv, aad, tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

function localEnvelopeEncrypt(secretBuffer, context) {
  const aad = Buffer.from(JSON.stringify(context), 'utf8');
  const dataKey = crypto.randomBytes(32);
  const wrapped = encryptAesGcm({
    plaintext: dataKey,
    key: getLocalKek(),
    aad,
  });
  const sealed = encryptAesGcm({
    plaintext: secretBuffer,
    key: dataKey,
    aad,
  });
  dataKey.fill(0);

  return {
    v: 1,
    kind: 'wallet-secret-envelope',
    provider: LOCAL_PROVIDER,
    algorithm: 'aes-256-gcm',
    context,
    wrapped_key: bufferToB64(wrapped.ciphertext),
    wrapped_key_iv: bufferToB64(wrapped.iv),
    wrapped_key_tag: bufferToB64(wrapped.tag),
    ciphertext: bufferToB64(sealed.ciphertext),
    iv: bufferToB64(sealed.iv),
    tag: bufferToB64(sealed.tag),
  };
}

function localEnvelopeDecrypt(envelope) {
  const aad = Buffer.from(JSON.stringify(envelope.context || {}), 'utf8');
  const dataKey = decryptAesGcm({
    ciphertext: b64ToBuffer(envelope.wrapped_key),
    key: getLocalKek(),
    iv: b64ToBuffer(envelope.wrapped_key_iv),
    aad,
    tag: b64ToBuffer(envelope.wrapped_key_tag),
  });

  try {
    return decryptAesGcm({
      ciphertext: b64ToBuffer(envelope.ciphertext),
      key: dataKey,
      iv: b64ToBuffer(envelope.iv),
      aad,
      tag: b64ToBuffer(envelope.tag),
    });
  } finally {
    dataKey.fill(0);
  }
}

function getAwsCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  const sessionToken = process.env.AWS_SESSION_TOKEN;

  if (!accessKeyId || !secretAccessKey) {
    throw new Error('AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY are required for WALLET_SECRET_PROVIDER=aws-kms');
  }

  return { accessKeyId, secretAccessKey, sessionToken };
}

function sha256Hex(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function hmac(key, value, encoding) {
  return crypto.createHmac('sha256', key).update(value).digest(encoding);
}

function deriveAwsSigningKey(secretAccessKey, dateStamp, region, service) {
  const kDate = hmac(`AWS4${secretAccessKey}`, dateStamp);
  const kRegion = hmac(kDate, region);
  const kService = hmac(kRegion, service);
  return hmac(kService, 'aws4_request');
}

function toAmzDate(now = new Date()) {
  return now.toISOString().replace(/[:-]|\.\d{3}/g, '');
}

function getAwsKmsHost() {
  return process.env.WALLET_SECRET_KMS_ENDPOINT_HOST || `kms.${process.env.AWS_REGION}.amazonaws.com`;
}

function getAwsKmsPath() {
  return process.env.WALLET_SECRET_KMS_ENDPOINT_PATH || '/';
}

function buildAwsHeaders(target, body) {
  const region = process.env.AWS_REGION;
  const keyId = process.env.WALLET_SECRET_KMS_KEY_ID;
  if (!region || !keyId) {
    throw new Error('AWS_REGION and WALLET_SECRET_KMS_KEY_ID are required for WALLET_SECRET_PROVIDER=aws-kms');
  }

  const host = getAwsKmsHost();
  const path = getAwsKmsPath();
  const { accessKeyId, secretAccessKey, sessionToken } = getAwsCredentials();
  const amzDate = toAmzDate();
  const dateStamp = amzDate.slice(0, 8);

  const headers = {
    'content-type': 'application/x-amz-json-1.1',
    host,
    'x-amz-date': amzDate,
    'x-amz-target': target,
  };
  if (sessionToken) {
    headers['x-amz-security-token'] = sessionToken;
  }

  const sortedHeaderNames = Object.keys(headers).sort();
  const canonicalHeaders = sortedHeaderNames
    .map((name) => `${name}:${String(headers[name]).trim()}\n`)
    .join('');
  const signedHeaders = sortedHeaderNames.join(';');
  const payloadHash = sha256Hex(body);
  const canonicalRequest = [
    'POST',
    path,
    '',
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join('\n');

  const credentialScope = `${dateStamp}/${region}/kms/aws4_request`;
  const stringToSign = [
    'AWS4-HMAC-SHA256',
    amzDate,
    credentialScope,
    sha256Hex(canonicalRequest),
  ].join('\n');

  const signingKey = deriveAwsSigningKey(secretAccessKey, dateStamp, region, 'kms');
  const signature = hmac(signingKey, stringToSign, 'hex');
  headers.authorization = [
    `AWS4-HMAC-SHA256 Credential=${accessKeyId}/${credentialScope}`,
    `SignedHeaders=${signedHeaders}`,
    `Signature=${signature}`,
  ].join(', ');

  return { headers, host, path };
}

function kmsRequest(target, payload) {
  const body = JSON.stringify(payload);
  const { headers, host, path } = buildAwsHeaders(target, body);

  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host,
        path,
        method: 'POST',
        headers: {
          ...headers,
          'content-length': Buffer.byteLength(body),
        },
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const responseBody = Buffer.concat(chunks).toString('utf8');
          let parsed;
          try {
            parsed = responseBody ? JSON.parse(responseBody) : {};
          } catch (_err) {
            return reject(new Error(`KMS returned non-JSON response (${res.statusCode})`));
          }

          if (res.statusCode >= 200 && res.statusCode < 300) {
            return resolve(parsed);
          }

          const errorMessage = parsed.message || parsed.Message || parsed.__type || `status ${res.statusCode}`;
          return reject(new Error(`KMS request failed: ${errorMessage}`));
        });
      }
    );

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function awsKmsEnvelopeEncrypt(secretBuffer, context) {
  const dataKeyResponse = await kmsRequest('TrentService.GenerateDataKey', {
    KeyId: process.env.WALLET_SECRET_KMS_KEY_ID,
    KeySpec: 'AES_256',
    EncryptionContext: context,
  });

  const dataKey = b64ToBuffer(dataKeyResponse.Plaintext);
  try {
    const aad = Buffer.from(JSON.stringify(context), 'utf8');
    const sealed = encryptAesGcm({
      plaintext: secretBuffer,
      key: dataKey,
      aad,
    });

    return {
      v: 1,
      kind: 'wallet-secret-envelope',
      provider: AWS_KMS_PROVIDER,
      algorithm: 'aes-256-gcm',
      kms_key_id: dataKeyResponse.KeyId || process.env.WALLET_SECRET_KMS_KEY_ID,
      encrypted_data_key: dataKeyResponse.CiphertextBlob,
      context,
      ciphertext: bufferToB64(sealed.ciphertext),
      iv: bufferToB64(sealed.iv),
      tag: bufferToB64(sealed.tag),
    };
  } finally {
    dataKey.fill(0);
  }
}

async function awsKmsEnvelopeDecrypt(envelope) {
  const response = await kmsRequest('TrentService.Decrypt', {
    CiphertextBlob: envelope.encrypted_data_key,
    EncryptionContext: envelope.context,
    KeyId: envelope.kms_key_id,
  });

  const dataKey = b64ToBuffer(response.Plaintext);
  try {
    const aad = Buffer.from(JSON.stringify(envelope.context || {}), 'utf8');
    return decryptAesGcm({
      ciphertext: b64ToBuffer(envelope.ciphertext),
      key: dataKey,
      iv: b64ToBuffer(envelope.iv),
      aad,
      tag: b64ToBuffer(envelope.tag),
    });
  } finally {
    dataKey.fill(0);
  }
}

function validateWalletSecretConfig() {
  const provider = getConfiguredProvider();

  if (isProduction() && provider !== AWS_KMS_PROVIDER) {
    throw new Error('Production requires WALLET_SECRET_PROVIDER=aws-kms');
  }

  if (provider === LOCAL_PROVIDER) {
    getLocalKek();
    return;
  }

  if (provider === AWS_KMS_PROVIDER) {
    if (!process.env.AWS_REGION || !process.env.WALLET_SECRET_KMS_KEY_ID) {
      throw new Error('AWS_REGION and WALLET_SECRET_KMS_KEY_ID are required for WALLET_SECRET_PROVIDER=aws-kms');
    }
    getAwsCredentials();
    return;
  }

  throw new Error(`Unsupported WALLET_SECRET_PROVIDER: ${provider}`);
}

async function encryptWithProvider(secretBuffer, context) {
  const provider = getConfiguredProvider();
  if (provider === LOCAL_PROVIDER) return localEnvelopeEncrypt(secretBuffer, context);
  if (provider === AWS_KMS_PROVIDER) return awsKmsEnvelopeEncrypt(secretBuffer, context);
  throw new Error(`Unsupported WALLET_SECRET_PROVIDER: ${provider}`);
}

async function decryptWithProvider(envelope) {
  if (envelope.provider === LOCAL_PROVIDER) return localEnvelopeDecrypt(envelope);
  if (envelope.provider === AWS_KMS_PROVIDER) return awsKmsEnvelopeDecrypt(envelope);
  throw new Error(`Unsupported wallet secret provider in envelope: ${envelope.provider}`);
}

async function encryptWalletSecret(secret, contextInput = {}) {
  validateWalletSecretConfig();
  if (isEncryptedWalletSecret(secret)) return secret;

  const secretBuffer = Buffer.from(String(secret), 'utf8');
  try {
    const context = buildEncryptionContext(contextInput);
    const envelope = await encryptWithProvider(secretBuffer, context);
    return encodeEnvelope(envelope);
  } finally {
    secretBuffer.fill(0);
  }
}

async function decryptWalletSecretToBuffer(secret, contextInput = {}) {
  if (typeof secret !== 'string' || !secret) {
    throw new Error('Wallet secret is missing');
  }

  const envelope = parseEnvelope(secret);
  if (!envelope) {
    throw new Error('Wallet secret has invalid format: encrypted envelope required');
  }

  const expectedContext = buildEncryptionContext(contextInput);
  const envelopeContext = envelope.context || {};

  if (
    expectedContext.wallet_public_key &&
    envelopeContext.wallet_public_key !== expectedContext.wallet_public_key
  ) {
    throw new Error('Wallet secret context mismatch');
  }

  if (expectedContext.user_id && envelopeContext.user_id && envelopeContext.user_id !== expectedContext.user_id) {
    throw new Error('Wallet secret owner mismatch');
  }

  return decryptWithProvider(envelope);
}

async function withDecryptedWalletSecret(secret, contextInput, fn) {
  const secretBuffer = await decryptWalletSecretToBuffer(secret, contextInput);
  let plaintextSecret = secretBuffer.toString('utf8');
  try {
    return await fn(plaintextSecret);
  } finally {
    secretBuffer.fill(0);
    plaintextSecret = null;
  }
}

async function rotateLegacyUserWalletSecrets({ runner = db, dryRun = false } = {}) {
  const { rows } = await runner.query(
    'SELECT id, wallet_public_key, wallet_secret_encrypted FROM users ORDER BY created_at ASC, id ASC'
  );

  let rotated = 0;
  let alreadyEncrypted = 0;
  let invalid = 0;

  for (const row of rows) {
    if (isEncryptedWalletSecret(row.wallet_secret_encrypted)) {
      alreadyEncrypted += 1;
      continue;
    }

    if (!isLegacyPlaintextWalletSecret(row.wallet_secret_encrypted)) {
      invalid += 1;
      continue;
    }

    const encryptedSecret = await encryptWalletSecret(row.wallet_secret_encrypted, {
      userId: row.id,
      walletPublicKey: row.wallet_public_key,
    });

    if (!dryRun) {
      await runner.query(
        'UPDATE users SET wallet_secret_encrypted = $1 WHERE id = $2',
        [encryptedSecret, row.id]
      );
    }
    rotated += 1;
  }

  return {
    total: rows.length,
    rotated,
    alreadyEncrypted,
    invalid,
  };
}

async function countLegacyPlaintextUserWalletSecrets({ runner = db } = {}) {
  const { rows } = await runner.query('SELECT wallet_secret_encrypted FROM users');
  return rows.reduce(
    (count, row) => count + (isLegacyPlaintextWalletSecret(row.wallet_secret_encrypted) ? 1 : 0),
    0
  );
}

async function assertNoLegacyPlaintextUserWalletSecrets({ runner = db } = {}) {
  const count = await countLegacyPlaintextUserWalletSecrets({ runner });
  if (count > 0) {
    throw new Error(
      `Detected ${count} legacy plaintext wallet secret(s); run npm run rotate-wallet-secrets before production startup`
    );
  }
}

module.exports = {
  assertNoLegacyPlaintextUserWalletSecrets,
  countLegacyPlaintextUserWalletSecrets,
  decryptWalletSecretToBuffer,
  encryptWalletSecret,
  getConfiguredProvider,
  isEncryptedWalletSecret,
  isLegacyPlaintextWalletSecret,
  rotateLegacyUserWalletSecrets,
  validateWalletSecretConfig,
  withDecryptedWalletSecret,
};

'use strict';

/**
 * TtlCache unit tests — no DB or network required.
 * Run: NODE_ENV=test node --test src/utils/TtlCache.test.js
 */

const { describe, it, before, after } = require('node:test');
const assert = require('node:assert/strict');
const { TtlCache } = require('./TtlCache');

// ---------------------------------------------------------------------------
// get / set / has
// ---------------------------------------------------------------------------
describe('TtlCache — get/set/has', () => {
  it('returns undefined for missing keys', () => {
    const cache = new TtlCache(1000);
    assert.equal(cache.get('missing'), undefined);
  });

  it('stores and retrieves a value', () => {
    const cache = new TtlCache(1000);
    cache.set('key', 42);
    assert.equal(cache.get('key'), 42);
  });

  it('has() returns true for a live entry', () => {
    const cache = new TtlCache(1000);
    cache.set('x', 'hello');
    assert.equal(cache.has('x'), true);
  });

  it('has() returns false for a missing entry', () => {
    const cache = new TtlCache(1000);
    assert.equal(cache.has('nope'), false);
  });

  it('stores falsy values correctly (0, false, null, empty string)', () => {
    const cache = new TtlCache(1000);
    cache.set('zero', 0);
    cache.set('false', false);
    cache.set('null', null);
    cache.set('empty', '');
    // All should be returned as-is; 0/false/null/''/[] are truthy checks
    // that would incorrectly bypass cache — verify we handle them
    assert.equal(cache.get('zero'), 0);
    assert.equal(cache.get('false'), false);
    assert.equal(cache.get('null'), null);
    assert.equal(cache.get('empty'), '');
  });
});

// ---------------------------------------------------------------------------
// TTL expiry
// ---------------------------------------------------------------------------
describe('TtlCache — TTL expiry', () => {
  it('returns undefined after TTL expires', async () => {
    const cache = new TtlCache(50); // 50ms TTL
    cache.set('k', 'value');
    assert.equal(cache.get('k'), 'value');

    await new Promise((r) => setTimeout(r, 80));
    assert.equal(cache.get('k'), undefined);
  });

  it('per-entry TTL overrides the default', async () => {
    const cache = new TtlCache(5000); // long default
    cache.set('short', 'x', 40); // 40ms override
    assert.equal(cache.get('short'), 'x');

    await new Promise((r) => setTimeout(r, 70));
    assert.equal(cache.get('short'), undefined);
  });

  it('size excludes expired entries', async () => {
    const cache = new TtlCache(50);
    cache.set('a', 1);
    cache.set('b', 2);
    assert.equal(cache.size, 2);

    await new Promise((r) => setTimeout(r, 80));
    assert.equal(cache.size, 0);
  });
});

// ---------------------------------------------------------------------------
// wrap()
// ---------------------------------------------------------------------------
describe('TtlCache — wrap()', () => {
  it('calls the factory on cache miss', async () => {
    const cache = new TtlCache(1000);
    let calls = 0;
    const result = await cache.wrap('k', async () => { calls++; return 'value'; });
    assert.equal(result, 'value');
    assert.equal(calls, 1);
  });

  it('returns cached value without calling the factory again', async () => {
    const cache = new TtlCache(1000);
    let calls = 0;
    await cache.wrap('k', async () => { calls++; return 99; });
    const second = await cache.wrap('k', async () => { calls++; return 99; });
    assert.equal(second, 99);
    assert.equal(calls, 1); // factory called exactly once
  });

  it('re-calls the factory after TTL expires', async () => {
    const cache = new TtlCache(40); // 40ms
    let calls = 0;
    await cache.wrap('k', async () => { calls++; return 1; });
    await new Promise((r) => setTimeout(r, 70));
    await cache.wrap('k', async () => { calls++; return 2; });
    assert.equal(calls, 2);
  });

  it('does not cache when the factory throws', async () => {
    const cache = new TtlCache(1000);
    let calls = 0;
    const failing = () => cache.wrap('k', async () => { calls++; throw new Error('oops'); });
    await assert.rejects(failing, /oops/);
    await assert.rejects(failing, /oops/); // second call also hits the factory
    assert.equal(calls, 2);
  });

  it('prevents thundering herd — concurrent callers share one in-flight promise', async () => {
    const cache = new TtlCache(1000);
    let calls = 0;
    const factory = async () => {
      calls++;
      await new Promise((r) => setTimeout(r, 20));
      return 'shared';
    };

    const [r1, r2, r3] = await Promise.all([
      cache.wrap('k', factory),
      cache.wrap('k', factory),
      cache.wrap('k', factory),
    ]);

    assert.equal(r1, 'shared');
    assert.equal(r2, 'shared');
    assert.equal(r3, 'shared');
    assert.equal(calls, 1); // factory was only called once despite 3 concurrent callers
  });
});

// ---------------------------------------------------------------------------
// invalidate / invalidatePrefix / clear
// ---------------------------------------------------------------------------
describe('TtlCache — invalidation', () => {
  it('invalidate() removes a single key', () => {
    const cache = new TtlCache(1000);
    cache.set('a', 1);
    cache.set('b', 2);
    cache.invalidate('a');
    assert.equal(cache.get('a'), undefined);
    assert.equal(cache.get('b'), 2);
  });

  it('invalidatePrefix() removes all matching keys', () => {
    const cache = new TtlCache(1000);
    cache.set('admin:stats', 1);
    cache.set('admin:health', 2);
    cache.set('campaigns:featured', 3);
    cache.invalidatePrefix('admin:');
    assert.equal(cache.get('admin:stats'), undefined);
    assert.equal(cache.get('admin:health'), undefined);
    assert.equal(cache.get('campaigns:featured'), 3); // untouched
  });

  it('clear() removes all entries', () => {
    const cache = new TtlCache(1000);
    cache.set('a', 1);
    cache.set('b', 2);
    cache.set('c', 3);
    cache.clear();
    assert.equal(cache.size, 0);
    assert.equal(cache.get('a'), undefined);
  });
});

// ---------------------------------------------------------------------------
// size
// ---------------------------------------------------------------------------
describe('TtlCache — size', () => {
  it('size reflects current live entry count', () => {
    const cache = new TtlCache(1000);
    assert.equal(cache.size, 0);
    cache.set('a', 1);
    cache.set('b', 2);
    assert.equal(cache.size, 2);
    cache.invalidate('a');
    assert.equal(cache.size, 1);
  });
});

const { test } = require('node:test');
const assert = require('node:assert');
const { parsePagination, paginatedResponse } = require('./pagination');

test('parsePagination returns defaults for empty query', () => {
  const result = parsePagination({});
  assert.deepStrictEqual(result, { limit: 20, offset: 0 });
});

test('parsePagination respects custom defaults', () => {
  const result = parsePagination({}, { limit: 50, max: 200 });
  assert.deepStrictEqual(result, { limit: 50, offset: 0 });
});

test('parsePagination parses limit and offset from query', () => {
  const result = parsePagination({ limit: '10', offset: '5' });
  assert.deepStrictEqual(result, { limit: 10, offset: 5 });
});

test('parsePagination caps limit to max', () => {
  const result = parsePagination({ limit: '999' }, { limit: 20, max: 100 });
  assert.deepStrictEqual(result, { limit: 100, offset: 0 });
});

test('parsePagination floors offset to 0 for negative values', () => {
  const result = parsePagination({ offset: '-5' });
  assert.deepStrictEqual(result, { limit: 20, offset: 0 });
});

test('parsePagination treats non-numeric limit as default', () => {
  const result = parsePagination({ limit: 'abc' });
  assert.deepStrictEqual(result, { limit: 20, offset: 0 });
});

test('parsePagination treats limit=0 as default', () => {
  const result = parsePagination({ limit: '0' });
  assert.deepStrictEqual(result, { limit: 20, offset: 0 });
});
